-- Reconcile flag identification seed rows when the original migration was recorded
-- before its content seed was available. All rows remain inactive pending review.
BEGIN;
ALTER TABLE public.challenges ADD COLUMN IF NOT EXISTS asset_path TEXT;
ALTER TABLE public.challenges DROP CONSTRAINT IF EXISTS challenges_asset_path_safe;
ALTER TABLE public.challenges ADD CONSTRAINT challenges_asset_path_safe CHECK (asset_path IS NULL OR asset_path ~ '^/flags/[a-z]{2}\.svg$');
COMMIT;
